import "server-only";
import placeholders from "@/data/blur.json";
import type { ProjectMedia } from "@/data/projects";

const table = placeholders as Record<string, string>;

/**
 * The blurred placeholder for a piece of media: its poster for clips, the
 * image itself otherwise. Generated by `npm run blur` (runs before dev and
 * build); server-only so the table never ships to the browser.
 */
export const blurFor = (m: ProjectMedia) => table[m.type === "video" ? (m.poster ?? "") : m.src];
